class Solution:

	def palindromicPartition(self, s):
		dp = [[-1] * (len(s) + 1) for _ in range(len(s) + 1)]

		def dfs(s, i, j):
			if dp[i][j] != -1:
				return dp[i][j]
			if i > j:
				return 0
			if self.isPal(s, i, j):
				return 0
			mx = len(s)
			for k in range(i, j):
				if self.isPal(s, i, k):
					t = dfs(s, k + 1, j) + 1
					mx = min(mx, t)
			dp[i][j] = mx
			return dp[i][j]
		return dfs(s, 0, len(s) - 1)

	def isPal(self, s, start, end):
		while start <= end:
			if s[start] != s[end]:
				return False
			start += 1
			end -= 1
		return True
